--liquibase formatted sql

-- =============================================================================
-- 0002_reference_tables.sql — reference data: places, organisation, products.
--
-- Conventions used in every table of this schema:
--   * Surrogate keys are identity columns, GENERATED BY DEFAULT ON NULL: Oracle
--     fills them, but the seed data may still insert the v1 IDs explicitly.
--   * Constraint names: <table>_pk, <table>_<column>_uk, <table>_<column>_fk,
--     <table>_<rule>_ck. Index names: <table>_<column>_ix.
--   * Every foreign key column gets an index. Oracle does not create one
--     automatically, and without it, changing a parent row locks the whole
--     child table.
--   * created_at / created_by are filled automatically. created_by is the
--     session user: the employee when the app connects through proxy
--     authentication, WELBANK when Liquibase does.
--   * Tables and columns are documented with COMMENT, so the documentation
--     lives in the database (see USER_TAB_COMMENTS / USER_COL_COMMENTS).
-- =============================================================================

--changeset elomwarren:0002-regions
CREATE TABLE regions (
  region_id    NUMBER(10)    GENERATED BY DEFAULT ON NULL AS IDENTITY,
  region_name  VARCHAR2(40)  NOT NULL,
  created_at   TIMESTAMP     DEFAULT ON NULL SYSTIMESTAMP,
  created_by   VARCHAR2(128) DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT regions_pk      PRIMARY KEY (region_id),
  CONSTRAINT regions_name_uk UNIQUE (region_name)
);
COMMENT ON TABLE  regions             IS 'The administrative regions of Ghana.';
COMMENT ON COLUMN regions.region_name IS 'Official name, e.g. Greater Accra Region.';
--rollback DROP TABLE regions PURGE;

--changeset elomwarren:0002-branches
CREATE TABLE branches (
  branch_id    NUMBER(10)    GENERATED BY DEFAULT ON NULL AS IDENTITY,
  branch_code  VARCHAR2(10)  NOT NULL,
  branch_name  VARCHAR2(60)  NOT NULL,
  region_id    NUMBER(10)    NOT NULL,
  phone        phone_d       NOT NULL,
  status       VARCHAR2(10)  DEFAULT ON NULL 'OPEN',
  opened_on    DATE          NOT NULL,
  created_at   TIMESTAMP     DEFAULT ON NULL SYSTIMESTAMP,
  created_by   VARCHAR2(128) DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT branches_pk        PRIMARY KEY (branch_id),
  CONSTRAINT branches_code_uk   UNIQUE (branch_code),
  CONSTRAINT branches_name_uk   UNIQUE (branch_name),
  CONSTRAINT branches_region_fk FOREIGN KEY (region_id) REFERENCES regions (region_id),
  CONSTRAINT branches_status_ck CHECK (status IN ('OPEN', 'CLOSED'))
);
CREATE INDEX branches_region_ix ON branches (region_id);
COMMENT ON TABLE  branches             IS 'Bank branches.';
COMMENT ON COLUMN branches.branch_code IS 'Short business code shown to staff, e.g. ACC-ELG.';
COMMENT ON COLUMN branches.status      IS 'OPEN or CLOSED. Branches are closed, never deleted.';
--rollback DROP TABLE branches PURGE;

--changeset elomwarren:0002-locations
CREATE TABLE locations (
  location_id      NUMBER(10)           GENERATED BY DEFAULT ON NULL AS IDENTITY,
  branch_id        NUMBER(10)           NOT NULL,
  street_address   VARCHAR2(100)        NOT NULL,
  town             VARCHAR2(60)         NOT NULL,
  digital_address  gh_digital_address_d NOT NULL,
  landmark         VARCHAR2(200),
  created_at       TIMESTAMP            DEFAULT ON NULL SYSTIMESTAMP,
  created_by       VARCHAR2(128)        DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT locations_pk        PRIMARY KEY (location_id),
  CONSTRAINT locations_branch_uk UNIQUE (branch_id),
  CONSTRAINT locations_branch_fk FOREIGN KEY (branch_id) REFERENCES branches (branch_id)
);
COMMENT ON TABLE  locations                 IS 'Street address of each branch (one per branch). The region comes from the branch, not stored again here (third normal form).';
COMMENT ON COLUMN locations.digital_address IS 'GhanaPost GPS digital address.';
COMMENT ON COLUMN locations.landmark        IS 'Directions people actually use, e.g. "opposite the Shell filling station".';
--rollback DROP TABLE locations PURGE;

--changeset elomwarren:0002-departments
CREATE TABLE departments (
  department_id    NUMBER(10)    GENERATED BY DEFAULT ON NULL AS IDENTITY,
  department_name  VARCHAR2(60)  NOT NULL,
  created_at       TIMESTAMP     DEFAULT ON NULL SYSTIMESTAMP,
  created_by       VARCHAR2(128) DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT departments_pk      PRIMARY KEY (department_id),
  CONSTRAINT departments_name_uk UNIQUE (department_name)
);
COMMENT ON TABLE departments IS 'Departments of the bank (Customer service, Operations, Human resources, ...).';
--rollback DROP TABLE departments PURGE;

--changeset elomwarren:0002-jobs
CREATE TABLE jobs (
  job_id         NUMBER(10)       GENERATED BY DEFAULT ON NULL AS IDENTITY,
  job_title      VARCHAR2(60)     NOT NULL,
  department_id  NUMBER(10)       NOT NULL,
  min_salary     positive_money_d NOT NULL,
  max_salary     positive_money_d NOT NULL,
  created_at     TIMESTAMP        DEFAULT ON NULL SYSTIMESTAMP,
  created_by     VARCHAR2(128)    DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT jobs_pk            PRIMARY KEY (job_id),
  CONSTRAINT jobs_title_uk      UNIQUE (job_title),
  CONSTRAINT jobs_department_fk FOREIGN KEY (department_id) REFERENCES departments (department_id),
  CONSTRAINT jobs_salary_ck     CHECK (min_salary <= max_salary)
);
CREATE INDEX jobs_department_ix ON jobs (department_id);
COMMENT ON TABLE  jobs            IS 'Job titles with their yearly salary range (GHS).';
COMMENT ON COLUMN jobs.min_salary IS 'Lowest yearly salary for the job; never above max_salary.';
--rollback DROP TABLE jobs PURGE;

--changeset elomwarren:0002-currencies
CREATE TABLE currencies (
  currency_code  iso_currency_d NOT NULL,
  currency_name  VARCHAR2(40)   NOT NULL,
  symbol         VARCHAR2(5),
  minor_units    NUMBER(1)      DEFAULT ON NULL 2,
  is_active      BOOLEAN        DEFAULT ON NULL TRUE,
  created_at     TIMESTAMP      DEFAULT ON NULL SYSTIMESTAMP,
  created_by     VARCHAR2(128)  DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT currencies_pk          PRIMARY KEY (currency_code),
  CONSTRAINT currencies_name_uk     UNIQUE (currency_name),
  CONSTRAINT currencies_minor_ck    CHECK (minor_units BETWEEN 0 AND 3)
);
COMMENT ON TABLE  currencies             IS 'Currencies the bank holds accounts in. The ISO code is the key (a natural key: it never changes).';
COMMENT ON COLUMN currencies.minor_units IS 'Digits after the decimal point: 2 for GHS (pesewas) and USD (cents).';
COMMENT ON COLUMN currencies.is_active   IS 'SQL BOOLEAN (new in Oracle 23ai). FALSE = no new accounts in this currency.';
--rollback DROP TABLE currencies PURGE;

--changeset elomwarren:0002-account-products
CREATE TABLE account_products (
  product_id           NUMBER(10)           GENERATED BY DEFAULT ON NULL AS IDENTITY,
  product_code         VARCHAR2(20)         NOT NULL,
  product_name         VARCHAR2(60)         NOT NULL,
  account_type         VARCHAR2(15)         NOT NULL,
  currency_code        iso_currency_d       NOT NULL,
  interest_rate        rate_pct_d           DEFAULT ON NULL 0,
  min_opening_balance  non_negative_money_d DEFAULT ON NULL 0,
  min_balance          non_negative_money_d DEFAULT ON NULL 0,
  monthly_fee          non_negative_money_d DEFAULT ON NULL 0,
  overdraft_allowed    BOOLEAN              DEFAULT ON NULL FALSE,
  term_months          NUMBER(3),
  is_active            BOOLEAN              DEFAULT ON NULL TRUE,
  created_at           TIMESTAMP            DEFAULT ON NULL SYSTIMESTAMP,
  created_by           VARCHAR2(128)        DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT account_products_pk          PRIMARY KEY (product_id),
  CONSTRAINT account_products_code_uk     UNIQUE (product_code),
  CONSTRAINT account_products_currency_fk FOREIGN KEY (currency_code) REFERENCES currencies (currency_code),
  CONSTRAINT account_products_type_ck     CHECK (account_type IN ('SAVINGS', 'CURRENT', 'FIXED_DEPOSIT')),
  -- A fixed deposit has a term; other accounts do not. "IS NOT NULL" is needed:
  -- with a NULL term, "term_months > 0" is UNKNOWN (not FALSE), and a CHECK
  -- constraint only rejects FALSE, so the row would slip through.
  CONSTRAINT account_products_term_ck     CHECK (
    (account_type = 'FIXED_DEPOSIT' AND term_months IS NOT NULL AND term_months > 0) OR
    (account_type <> 'FIXED_DEPOSIT' AND term_months IS NULL)),
  -- Only current accounts may go overdrawn.
  CONSTRAINT account_products_overdraft_ck CHECK (overdraft_allowed = FALSE OR account_type = 'CURRENT')
);
CREATE INDEX account_products_currency_ix ON account_products (currency_code);
COMMENT ON TABLE  account_products               IS 'Account products the bank sells. Replaces the free-text acc_type of schema v1.';
COMMENT ON COLUMN account_products.interest_rate IS 'Annual interest paid on credit balances, in percent.';
COMMENT ON COLUMN account_products.term_months   IS 'Fixed deposits only: how long the money is locked.';
--rollback DROP TABLE account_products PURGE;

--changeset elomwarren:0002-loan-products
CREATE TABLE loan_products (
  product_id       NUMBER(10)       GENERATED BY DEFAULT ON NULL AS IDENTITY,
  product_code     VARCHAR2(20)     NOT NULL,
  product_name     VARCHAR2(60)     NOT NULL,
  currency_code    iso_currency_d   NOT NULL,
  interest_rate    rate_pct_d       NOT NULL,
  min_amount       positive_money_d NOT NULL,
  max_amount       positive_money_d NOT NULL,
  max_term_months  NUMBER(3)        NOT NULL,
  is_active        BOOLEAN          DEFAULT ON NULL TRUE,
  created_at       TIMESTAMP        DEFAULT ON NULL SYSTIMESTAMP,
  created_by       VARCHAR2(128)    DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT loan_products_pk          PRIMARY KEY (product_id),
  CONSTRAINT loan_products_code_uk     UNIQUE (product_code),
  CONSTRAINT loan_products_currency_fk FOREIGN KEY (currency_code) REFERENCES currencies (currency_code),
  CONSTRAINT loan_products_amount_ck   CHECK (min_amount <= max_amount),
  CONSTRAINT loan_products_term_ck     CHECK (max_term_months > 0)
);
CREATE INDEX loan_products_currency_ix ON loan_products (currency_code);
COMMENT ON TABLE  loan_products               IS 'Loan products: personal, mortgage, SME, ...';
COMMENT ON COLUMN loan_products.interest_rate IS 'Annual interest rate charged, in percent.';
--rollback DROP TABLE loan_products PURGE;

--changeset elomwarren:0002-transaction-limits
CREATE TABLE transaction_limits (
  limit_id       NUMBER(10)       GENERATED BY DEFAULT ON NULL AS IDENTITY,
  role_name      VARCHAR2(128)    NOT NULL,
  txn_type       txn_type_d       NOT NULL,
  currency_code  iso_currency_d   NOT NULL,
  max_amount     positive_money_d NOT NULL,
  created_at     TIMESTAMP        DEFAULT ON NULL SYSTIMESTAMP,
  created_by     VARCHAR2(128)    DEFAULT ON NULL SYS_CONTEXT('USERENV', 'SESSION_USER'),
  CONSTRAINT transaction_limits_pk          PRIMARY KEY (limit_id),
  CONSTRAINT transaction_limits_uk          UNIQUE (role_name, txn_type, currency_code),
  CONSTRAINT transaction_limits_currency_fk FOREIGN KEY (currency_code) REFERENCES currencies (currency_code),
  CONSTRAINT transaction_limits_role_ck     CHECK (role_name = UPPER(role_name))
);
CREATE INDEX transaction_limits_currency_ix ON transaction_limits (currency_code);
COMMENT ON TABLE  transaction_limits            IS 'Largest amount a role may post alone; above it, a supervisor must approve (maker-checker).';
COMMENT ON COLUMN transaction_limits.role_name  IS 'Oracle role, e.g. TELLER. Upper case, as Oracle stores role names.';
--rollback DROP TABLE transaction_limits PURGE;
